3:   { id: 1, nama: "Laptop Kerja Pro", kategori: "elektronik", harga: 12500000, emoji: "💻", desc: "Laptop bisnis ringan, RAM 16GB, SSD 512GB." },
4:   { id: 2, nama: "Router Gigabit", kategori: "elektronik", harga: 850000, emoji: "🌐", desc: "Router dual-band untuk jaringan kantor stabil." },
5:   { id: 3, nama: "Kamera CCTV HD", kategori: "elektronik", harga: 1450000, emoji: "📷", desc: "Kamera pengawas 1080p dengan night vision." },
6:   { id: 4, nama: "Obeng Set Lengkap", kategori: "perkakas", harga: 120000, emoji: "🔧", desc: "Set obeng 32 pcs untuk perbaikan presisi." },
7:   { id: 5, nama: "Bor Listrik 650W", kategori: "perkakas", harga: 675000, emoji: "🔨", desc: "Bor tangan bertenaga untuk pekerjaan berat." },
8:   { id: 6, nama: "Tang Hex Key Set", kategori: "perkakas", harga: 95000, emoji: "🪛", desc: "Set kunci hex 5–10 mm, baja chrome." },
9:   { id: 7, nama: "Printer A4 Multifungsi", kategori: "kantor", harga: 2150000, emoji: "🖨️", desc: "Cetak, scan, dan fotokopi dalam satu alat." },
10:   { id: 8, nama: "Buku Agenda 2025", kategori: "kantor", harga: 45000, emoji: "📓", desc: "Agenda harian hardcover isi 368 halaman." },
11:   { id: 9, nama: "Stapler Heavy Duty", kategori: "kantor", harga: 78000, emoji: "📎", desc: "Stapler kapasitas 100 lembar." },
12: ];
13: 
14: const formatRupiah = (n) => "Rp " + n.toLocaleString("id-ID");
15: 
16: function renderProducts(filter) {
17:   const grid = document.getElementById("product-grid");
18:   const items = filter === "semua" ? PRODUCTS : PRODUCTS.filter((p) => p.kategori === filter);
19: 
20:   grid.innerHTML = "";
21:   if (items.length === 0) {
22:     const empty = document.createElement("p");
23:     empty.className = "product-empty";
24:     empty.textContent = "Tidak ada produk pada kategori ini.";
25:     grid.appendChild(empty);
26:     return;
27:   }
28: 
29:   for (const p of items) {
30:     const card = document.createElement("article");
31:     card.className = "product-card";
32: 
33:     const img = document.createElement("div");
34:     img.className = "product-img";
35:     img.setAttribute("aria-hidden", "true");
36:     img.textContent = p.emoji;
37: 
38:     const body = document.createElement("div");
39:     body.className = "product-body";
40: 
41:     const cat = document.createElement("span");
42:     cat.className = "product-cat";
43:     cat.textContent = p.kategori;
44: 
45:     const title = document.createElement("h3");
46:     title.textContent = p.nama;
47: 
48:     const desc = document.createElement("p");
49:     desc.textContent = p.desc;
50: 
51:     const price = document.createElement("p");
52:     price.className = "product-price";
53:     price.textContent = formatRupiah(p.harga);
54: 
55:     body.append(cat, title, desc, price);
56:     card.append(img, body);
57:     grid.appendChild(card);
58:   }
59: }
60: 
61: function initCatalog() {
62:   const chips = document.querySelectorAll(".chip");
63:   chips.forEach((chip) => {
64:     chip.addEventListener("click", () => {
65:       chips.forEach((c) => c.classList.remove("active"));
66:       chip.classList.add("active");
67:       renderProducts(chip.dataset.filter);
68:     });
69:   });
70:   renderProducts("semua");
71: }
72: 
73: function initContactForm() {
74:   const form = document.getElementById("contact-form");
75:   const status = document.getElementById("form-status");
76:   form.addEventListener("submit", (e) => {
77:     e.preventDefault();
78:     if (!form.checkValidity()) {
79:       status.textContent = "Isi semua kolom dengan benar.";
80:       status.classList.add("error");
81:       return;
82:     }
83:     status.classList.remove("error");
84:     status.textContent = "Pesan terkirim! Tim kami akan segera merespons.";
85:     form.reset();
86:   });
87: }
88: 
89: document.addEventListener("DOMContentLoaded", () => {
90:   initCatalog();
91:   initContactForm();
92: });
